"use client"
import React, { useEffect, useRef, useState, useCallback } from "react";

export default function GameComponent() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [gameState, setGameState] = useState<"menu" | "playing" | "gameover">(
    "menu"
  );
  const [score, setScore] = useState(0);

  // mutable game data (no re‑render on every frame)
  const playerRef = useRef({ x: 0, y: 0, width: 40, height: 70, speed: 5 });
  const obstaclesRef = useRef<
    { x: number; y: number; w: number; h: number; speed: number }[]
  >([]);
  const lastTimeRef = useRef(0);
  const animationRef = useRef<number>();
  const keysRef = useRef<{ left: boolean; right: boolean }>({
    left: false,
    right: false,
  });
  const touchStartX = useRef<number | null>(null);

  // resize canvas to fill window
  const resizeCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    // reposition player after resize
    const p = playerRef.current;
    p.x = canvas.width / 2 - p.width / 2;
    p.y = canvas.height - p.height - 20;
  }, []);

  // start / restart game
  const startGame = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    // reset player
    const p = playerRef.current;
    p.x = canvas.width / 2 - p.width / 2;
    p.y = canvas.height - p.height - 20;
    // reset obstacles
    obstaclesRef.current = [];
    // reset score
    setScore(0);
    // reset time
    lastTimeRef.current = performance.now();
    setGameState("playing");
  }, []);

  // input handling
  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.code === "ArrowLeft") keysRef.current.left = true;
    if (e.code === "ArrowRight") keysRef.current.right = true;
    if (e.code === "Enter") {
      if (gameState !== "playing") startGame();
    }
  }, [gameState, startGame]);

  const handleKeyUp = useCallback((e: KeyboardEvent) => {
    if (e.code === "ArrowLeft") keysRef.current.left = false;
    if (e.code === "ArrowRight") keysRef.current.right = false;
  }, []);

  const handleTouchStart = useCallback((e: TouchEvent) => {
    if (gameState !== "playing") {
      startGame();
      return;
    }
    touchStartX.current = e.touches[0].clientX;
  }, [gameState, startGame]);

  const handleTouchMove = useCallback((e: TouchEvent) => {
    if (touchStartX.current === null) return;
    const delta = e.touches[0].clientX - touchStartX.current;
    const p = playerRef.current;
    p.x += delta * 0.2; // sensitivity
    touchStartX.current = e.touches[0].clientX;
  }, []);

  const handleTouchEnd = useCallback(() => {
    touchStartX.current = null;
  }, []);

  // main loop
  const loop = useCallback(
    (time: number) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const dt = (time - lastTimeRef.current) / 1000;
      lastTimeRef.current = time;

      // clear
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      if (gameState === "menu") {
        ctx.fillStyle = "#222";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("Mario Kart Mini", canvas.width / 2, canvas.height / 2 - 40);
        ctx.font = "24px sans-serif";
        ctx.fillText(
          "Press Enter / Tap to Start",
          canvas.width / 2,
          canvas.height / 2 + 20
        );
      } else if (gameState === "playing") {
        // update player
        const p = playerRef.current;
        if (keysRef.current.left) p.x -= p.speed;
        if (keysRef.current.right) p.x += p.speed;
        // keep inside bounds
        p.x = Math.max(0, Math.min(canvas.width - p.width, p.x));

        // draw track (simple gray background)
        ctx.fillStyle = "#555";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // draw player car (red)
        ctx.fillStyle = "#e53935";
        ctx.fillRect(p.x, p.y, p.width, p.height);

        // spawn obstacles
        if (Math.random() < 0.02) {
          const w = 40 + Math.random() * 40;
          const x = Math.random() * (canvas.width - w);
          obstaclesRef.current.push({
            x,
            y: -80,
            w,
            h: 30,
            speed: 200 + Math.random() * 100,
          });
        }

        // update & draw obstacles
        ctx.fillStyle = "#ffb300";
        obstaclesRef.current.forEach((ob) => {
          ob.y += ob.speed * dt;
          ctx.fillRect(ob.x, ob.y, ob.w, ob.h);
        });
        // remove off‑screen
        obstaclesRef.current = obstaclesRef.current.filter(
          (ob) => ob.y < canvas.height + 50
        );

        // collision detection
        const collided = obstaclesRef.current.some(
          (ob) =>
            p.x < ob.x + ob.w &&
            p.x + p.width > ob.x &&
            p.y < ob.y + ob.h &&
            p.y + p.height > ob.y
        );
        if (collided) {
          setGameState("gameover");
        }

        // update score
        setScore((s) => s + Math.round(dt * 100));
        // draw score
        ctx.fillStyle = "#fff";
        ctx.font = "20px sans-serif";
        ctx.textAlign = "left";
        ctx.fillText(`Score: ${score}`, 10, 30);
      } else if (gameState === "gameover") {
        ctx.fillStyle = "#000a";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("Game Over", canvas.width / 2, canvas.height / 2 - 40);
        ctx.font = "24px sans-serif";
        ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2);
        ctx.fillText(
          "Press Enter / Tap to Restart",
          canvas.width / 2,
          canvas.height / 2 + 40
        );
      }

      animationRef.current = requestAnimationFrame(loop);
    },
    [gameState, score]
  );

  // mount / unmount
  useEffect(() => {
    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    window.addEventListener("touchstart", handleTouchStart);
    window.addEventListener("touchmove", handleTouchMove);
    window.addEventListener("touchend", handleTouchEnd);
    animationRef.current = requestAnimationFrame(loop);

    return () => {
      window.removeEventListener("resize", resizeCanvas);
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
      window.removeEventListener("touchstart", handleTouchStart);
      window.removeEventListener("touchmove", handleTouchMove);
      window.removeEventListener("touchend", handleTouchEnd);
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [
    resizeCanvas,
    handleKeyDown,
    handleKeyUp,
    handleTouchStart,
    handleTouchMove,
    handleTouchEnd,
    loop,
  ]);

  return (
    <div
      style={{
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        touchAction: "none",
      }}
    >
      <canvas
        ref={canvasRef}
        style={{ width: "100%", height: "100%", display: "block" }}
      />
    </div>
  );
}
